import Foundation
import JarvisCore
import JarvisTools
import Testing

/// ToolCatalog.swift is generated by tools/gen_tool_catalog.py from the m3_tool_schemas fixture,
/// which records what the REAL _build_claude_server() hands the SDK for each tool (plan §3.7).
@Suite("ToolCatalogTests")
struct ToolCatalogTests {
    /// This target has no JarvisTestSupport, so the fixture is found from #filePath.
    static func fixtureCases() throws -> [JSONObject] {
        let url = URL(fileURLWithPath: #filePath)
            .deletingLastPathComponent().deletingLastPathComponent()
            .appending(path: "Fixtures/golden/m3_tool_schemas.golden.json")
        let envelope = try #require(try PyJSON.loads(Data(contentsOf: url)).objectValue)
        #expect(envelope["suite"]?.stringValue == "m3_tool_schemas")
        return try #require(envelope["cases"]?.arrayValue).compactMap(\.objectValue)
    }

    @Test func catalogEqualsTheFixtureExactly() throws {
        let cases = try Self.fixtureCases()
        #expect(cases.count == 46)
        #expect(ToolCatalog.tools.count == cases.count)
        for (i, (tool, c)) in zip(ToolCatalog.tools, cases).enumerated() {
            let expected = try #require(c["expected"]?.objectValue)
            #expect(c["input"]?.objectValue?["index"] == .int(Int64(i)))
            #expect(tool.name == expected["name"]?.stringValue)
            #expect(tool.description == expected["description"]?.stringValue, "\(tool.name)")
            let parameters = try #require(expected["parameters"])
            // Byte-equal to Python's json.dumps of the schema, so key order is Python's too.
            #expect(tool.parametersJSON == PyJSON.dumps(parameters), "\(tool.name)")
            #expect(try PyJSON.loads(Data(tool.parametersJSON.utf8)) == parameters, "\(tool.name)")
        }
    }

    @Test func catalogNamesAreTheGatewayToolNamesInOrder() {
        #expect(ToolCatalog.tools.map(\.name) == DataSourceMap.toolNames)
    }
}
